def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    r0 = min(r for r, c in cells)
    r1 = max(r for r, c in cells)
    c0 = min(c for r, c in cells)
    c1 = max(c for r, c in cells)

    # Extend each row of the rectangle toward an edge unless a marker
    # lies beyond that side.
    for r in range(r0, r1 + 1):
        if not any(grid[r][c] != 0 and grid[r][c] != 2 for c in range(c0)):
            for c in range(c0):
                out[r][c] = 2
        if not any(grid[r][c] != 0 and grid[r][c] != 2 for c in range(c1 + 1, w)):
            for c in range(c1 + 1, w):
                out[r][c] = 2

    # Extend each column upward/downward under the same rule.
    for c in range(c0, c1 + 1):
        if not any(grid[r][c] != 0 and grid[r][c] != 2 for r in range(r0)):
            for r in range(r0):
                out[r][c] = 2
        if not any(grid[r][c] != 0 and grid[r][c] != 2 for r in range(r1 + 1, h)):
            for r in range(r1 + 1, h):
                out[r][c] = 2

    return out
